package runstate

import (
	"fmt"
)

// The prediction score record (tick jlv): the self-measurement gvc designs,
// generated by the factory operating rather than by anybody building it.
//
// A prediction made while an acceptance item was unrunnable becomes CHECKABLE
// the moment that item becomes runnable — the epic finishing is what makes the
// item runnable — and what the classifier said against what the done actually
// did is a labelled pair. The pair is the only evidence anyone will ever have
// for where the absorb threshold belongs: gvc set that threshold (gating's
// AbsorbThreshold) by argument rather than measurement, and wne's 49-tick
// sample could only test face validity, because every tick ran at its role's
// base model and no capability boundary was ever exercised. Here the ground
// truth arrives on its own, as a consequence of the epic finishing.
//
// The record carries BOTH HALVES, not a pointer between them: the prediction's
// own essentials (gating, item, confidence, the fallback when no model
// answered) and the outcome's own evidence (the check that ran, the commit it
// ran on, what it wrote, how it exited), so a later measurement ACROSS EPICS
// reads one record per pair and never walks back through the absorption
// decisions to reconstruct half of what the classifier is being calibrated
// against. The absorption record remains the decision; this is its grade.
//
// It lives at `.ticfac/runs/<run-id>/predictions/<key>.json`, keyed by the
// finding's dedup key — the same key the absorption record carries — and it is
// create-if-absent like every other decision record here: a prediction is
// scored once, however many incarnations the run takes, and an incarnation
// killed between the command and the record is resumed by the record's
// absence.

// The score vocabulary. These are gating's Score values (tick jlv declares
// them there), spelled here because runstate is the layer BELOW gating and
// cannot import it — the same one-spelling-per-layer rule the absorption
// record keeps for the basis vocabulary.
const (
	// PredictionScoreCorrect: the run agreed with the prediction — the item's
	// command answered fail, the done did not demonstrate the item, and the
	// finding was gating as predicted.
	PredictionScoreCorrect = "correct"
	// PredictionScoreIncorrect: the run disagreed — the item's command
	// passed on the tree the close-out scores, the done demonstrated the item
	// as the epic hands it over. Recorded, never hidden: a wrong prediction
	// is the evidence the threshold's next reader needs.
	PredictionScoreIncorrect = "incorrect"
)

// PredictionScoreValues is the closed score vocabulary.
var PredictionScoreValues = []string{PredictionScoreCorrect, PredictionScoreIncorrect}

// PredictionScore is one checked prediction, at
// `.ticfac/runs/<run-id>/predictions/<key>.json`, where <key> is the finding's
// dedup key — the prediction the absorption record under the same key made.
type PredictionScore struct {
	SchemaVersion int `json:"schema_version"`
	// Key is the finding the prediction was about — the draft's dedup key,
	// the absorption's key, and this record's file name. The pair is joined
	// on it.
	Key string `json:"key"`
	// ItemID is the acceptance item that became runnable and was run: the
	// item the prediction named. The check is per item, never borrowed.
	ItemID string `json:"item_id"`
	// PredictedGating is what the prediction said: the finding gates the done
	// via this item. Always true of a scored prediction — a non-gating
	// verdict names no item, and the fallback that named none is reported
	// unchecked rather than half-scored.
	PredictedGating bool `json:"predicted_gating"`
	// Confidence is the prediction's own confidence, carried here so the
	// later measurement reads the pair without walking to the absorption:
	// calibrating the threshold is calibrating against THIS number. Zero for
	// the fallback, which no model answered.
	Confidence float64 `json:"confidence,omitempty"`
	// Fallback, when non-empty, is why no model answered — the prediction
	// was the documented absorb fallback standing in for one.
	Fallback string `json:"fallback,omitempty"`
	// Score is the label: correct — the run agreed with the prediction; or
	// incorrect — the run disagreed, and the done demonstrated the item as
	// the epic hands it over.
	Score string `json:"score"`
	// Reason says what the run showed and what that does to the prediction,
	// written for the retro a person reads.
	Reason string `json:"reason"`
	// Check is the command that was run — the item's bound command, the one
	// command the evidence table authorises for it.
	Check Check `json:"check"`
	// Commit is the commit the command ran on — the key of the observation
	// the score rests on. A score keyed by nothing is a timestamped opinion.
	Commit string `json:"commit"`
	// Result is what the command added up to, in the gate's own vocabulary:
	// pass or fail — the two results that are evidence. Error and skipped
	// produced no evidence, and an item that stays unresolved is never
	// scored, so neither can appear here.
	Result string `json:"result"`
	// ExitCode is the command's exit status: zero for pass, the command's own
	// non-zero for fail.
	ExitCode int `json:"exit_code"`
	// Output is what the command wrote, bounded at the gate's own bound.
	Output InlineOutput `json:"output"`
	// StartedAt and FinishedAt are when the command ran, RFC3339, as the
	// runner observed them.
	StartedAt  string `json:"started_at,omitempty"`
	FinishedAt string `json:"finished_at,omitempty"`
	// ScoredAt is when the run scored the prediction, RFC3339 — the
	// close-out's own moment, the one the epic's ground truth arrives at.
	ScoredAt string `json:"scored_at"`

	Provenance Provenance `json:"provenance"`
}

// Validate applies the record's own rules: the closed score vocabulary, the
// outcome's agreement with the label it carries (a correct prediction is one
// whose item's command FAILED — the done did not demonstrate the item — and
// an incorrect one is one whose command PASSED), the pair's completeness
// (both halves: what was predicted, what ran, keyed by the commit it ran on),
// and the same discipline every other decision record here is held to — a
// score nobody can attribute is one nobody can audit.
func (p PredictionScore) Validate() error {
	if p.SchemaVersion != SchemaVersion {
		return fmt.Errorf("prediction score schema_version is %d, want %d", p.SchemaVersion, SchemaVersion)
	}
	if err := checkSegment("prediction score key", p.Key); err != nil {
		return err
	}
	if p.ItemID == "" {
		return fmt.Errorf("prediction score of %s names no item: the check is of the item the prediction named, "+
			"and a score of no item is a label with nothing under it", p.Key)
	}
	if !p.PredictedGating {
		return fmt.Errorf("prediction score of %s is of a prediction that broke no item: a non-gating verdict "+
			"names nothing to run and nothing to check, and scoring it would dress an echo up as calibration data", p.Key)
	}
	if !oneOf(p.Score, PredictionScoreValues) {
		return fmt.Errorf("prediction score %q is not one of %v", p.Score, PredictionScoreValues)
	}
	if !oneOf(p.Result, []string{"pass", "fail"}) {
		return fmt.Errorf("prediction score of %s rests on a command that answered %q: the outcome a score rests on "+
			"is a command that produced evidence (pass or fail), and an item that stayed unresolved is never scored",
			p.Key, p.Result)
	}
	if (p.Score == PredictionScoreCorrect) != (p.Result == "fail") {
		if p.Score == PredictionScoreCorrect {
			return fmt.Errorf("prediction score of %s says correct but the item was demonstrated: a correct "+
				"prediction is one whose item's command FAILED — the done did not demonstrate the item", p.Key)
		}
		return fmt.Errorf("prediction score of %s says incorrect but the item's command failed: an incorrect "+
			"prediction is one the run disagreed with, and the done demonstrated the item", p.Key)
	}
	if p.Check.ID == "" {
		return fmt.Errorf("prediction score of %s names no check: the score says what ran, and a score of a "+
			"command it cannot name is one nobody can replay", p.Key)
	}
	if p.Commit == "" {
		return fmt.Errorf("prediction score of %s is keyed by no commit: an observed record keyed by nothing is "+
			"a timestamped opinion, and this label is what a later measurement trusts", p.Key)
	}
	if p.Reason == "" {
		return fmt.Errorf("prediction score of %s carries no reason: a label that cannot say what it rests on is "+
			"one nobody can audit or replay", p.Key)
	}
	if p.ScoredAt == "" {
		return fmt.Errorf("prediction score of %s has no scored_at", p.Key)
	}
	if p.Confidence < 0 || p.Confidence > 1 {
		return fmt.Errorf("prediction score of %s carries confidence %.2f, which is not a probability",
			p.Key, p.Confidence)
	}
	return p.Provenance.validate()
}
